class DiagnosisProbe:
    def run_full_diagnosis(self, train_loader):
        state = capture_modes_and_rng()
        try:
            view.model.eval()
            metrics, definitions = existing_family_safe_diagnostics(train_loader)
            traces = get_actual_sampler_traces_if_supported()
            if traces is unavailable:
                record_null_with_reason('sampler_provenance')
            else:
                for trace in traces:
                    expected = reconstruct_from_public_training_history(trace)
                    check_source_indices_and_declared_crop(expected, trace)
                    check_same_event_targets_and_corruption_policy(expected, trace)
                    if trace.branch == 'terminal':
                        check_all_context_event_indices_precede_target(trace)
                    check_left_padding_reserved_ids_and_tensor_alignment(trace)
                    accumulate_per_assertion_counts_and_failures()
                for clean_record in bounded_control_records(traces):
                    require_clean_control_pass(clean_record)
                    for fault in ['shift_label_index', 'restore_masked_target']:
                        mutant = isolated_copy_with_fault(clean_record, fault)
                        record_detection_by_assertion(mutant, fault)
            return {'metrics': metrics, 'metric_definitions': definitions}
        finally:
            restore_modes_and_rng(state)

